SELECT A.BOOKSET_ID AS booksetId, /** 账套代码 **/ A.BOK_DETAIL_ID AS bokDetailId, /** 账务明细代码 **/ E.TYPE_18 as secType, /** 证券类型**/ E.TYPE_1 as assetType, /**资产类型 **/ nvl(B.TRADE_MARKET,C.TRADE_MARKET) as tradeMarket, /** 交易市场 **/ B.ISSUE_TYPE as issueType, /** 发行方式 **/ B.ISSUER AS issuer; /**发行人**/ C.COUNTER_ID as counterId, /** 交易对手 **/ A.BUSI_DETAIL_TYPE as accountType, /** 账户类型 **/ NVL(B.REGIST_ORG, D.REGIST_ORG) as feeType /**登记托管机构（费用类型）**/ FROM BOK_DETAIL_ID A LEFT JOIN FIN_PRODUCT B ON A.BUSI_ID = B.FINPROD_ID AND A.BUSI_DETAIL_TYPE = B.FINPROD_TYPE LEFT JOIN FIN_TRADE_PRODUCT C ON A.BUSI_ID = C.FINPROD_ID AND A.BUSI_DETAIL_TYPE = C.FINPROD_TYPE AND C.BRANCH = 0 LEFT JOIN FIN_TRADE_PRODUCT_ADD D ON D.FINPROD_ID = A.BUSI_ID AND D.BRANCH = 0 LEFT JOIN FIN_PRODUCT_TYPE E ON A.BUSI_ID = E.FINPROD_ID WHERE A.BOOKSET_ID = #{booksetId}
AND A.BOK_DETAIL_ID IN
null) OR A.BOK_DETAIL_ID IN (
